import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.BS0bAV7E.js";const _=JSON.parse('{"title":"版本方案","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/versioning.md","filePath":"zh/release/versioning.md"}'),r={name:"zh/release/versioning.md"};function c(i,e,l,s,n,h){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="版本方案" tabindex="-1">版本方案 <a class="header-anchor" href="#版本方案" aria-label="Permalink to &quot;版本方案&quot;">​</a></h1><h2 id="方案" tabindex="-1">方案 <a class="header-anchor" href="#方案" aria-label="Permalink to &quot;方案&quot;">​</a></h2><p>自 v1.0.0 公开发布起，版本号采用 <strong>SemVer</strong>：<code>1.0.0</code>、<code>2.0.0</code>、 <code>2.1.0</code>……在此之前，工程阶段使用工作包阶段名 （<code>WP-14-docs_release</code>、<code>WP-13-build_system</code>……）——按功能集划分的 发布列车的内部等价物。自 v2.0.0 起 tag 就是 <code>v&lt;版本&gt;</code> （<code>git tag v2.1.0</code>），<code>WP-*</code> tag 只存在于历史。</p><p>此外每个构建携带：</p><ul><li><strong>构建号</strong> = 构建时的提交计数（<code>git rev-list --count HEAD</code>） <strong>加永久的 +21 对齐偏移</strong>（Makefile 里的 <code>OC_KERNEL_BUILD_OFFSET := 21</code>）。偏移源自 v1.0.0：已发布的构建号 曾在一个 git 历史比公开仓 main 长 21 个提交的工程树上烙制 （WP-14-docs_release 在公开计数 253 时发布了 build 274），而 OTA 更新检查对构建号做<strong>数值</strong>比较（BUG-0347）——公开序列必须继续 高于已发布的 274。一提交一构建的单调性由此保持：v1.0.0 tag 位于 公开计数 257 -&gt; build 278；v2.0.0 位于计数 281 -&gt; build 302。</li><li><strong>版本横幅</strong> = Makefile 里冻结的 <code>OC_RELEASE_VERSION ?=</code> 字面量 （显式 <code>OC_RELEASE_VERSION=</code> 覆盖仍然有效——E2E 更新测试就是这么 跑的）——烙入内核横幅、uname、OTA 清单与 ISO。更早的构建从 <code>git describe --tags</code> 推导；v1.0.0 起冻结为字面量，横幅不再依赖 本地 git 状态。</li></ul><h2 id="数字如何对应" tabindex="-1">数字如何对应 <a class="header-anchor" href="#数字如何对应" aria-label="Permalink to &quot;数字如何对应&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>示例</th><th>含义</th></tr></thead><tbody><tr><td><code>uname -a</code></td><td><code>Open Cube OS 2.1.0 x86_64</code></td><td>运行中内核的版本</td></tr><tr><td>update.json</td><td><code>version: 2.1.0, build: &lt;n&gt;</code></td><td>已发布的清单</td></tr><tr><td>Release tag</td><td><code>v2.1.0</code></td><td>资产构建所用的 git tag</td></tr><tr><td>gh-pages</td><td>下载页同样的两个数字</td><td>网站镜像 Release</td></tr></tbody></table><p>一个发布 = 一个 tag = 一个构建号 = 一个清单 = 一组跨 本地 / Release / gh-pages / 私密镜像一致的 SHA256。tag 必须指向 CI 绿的提交（2.1.0 发布门）。</p><h2 id="兼容性承诺" tabindex="-1">兼容性承诺 <a class="header-anchor" href="#兼容性承诺" aria-label="Permalink to &quot;兼容性承诺&quot;">​</a></h2><ul><li>Shell 命令不经申报不删除；增加是常态。v1.0.0 的 233 条命令基线 完整保留：每一条都在 <code>INTERFACES.md</code> Part 1c 兼容契约里有映射 （v2 命令归属 251 = L0 99 + SVC 133 + 内建 19）。</li><li>L1SVC 操作号永不重编；新操作只追加（2.1.0 为 17 类 / 158 操作）。 退役的 v1 编号面的逐条归宿：<code>INTERFACES.md</code> Part 2c/2d。</li><li>OTA 包只更新内核；/etc 卷内容向前携带。</li><li>此后按 SemVer：破坏性变更升 MAJOR，新命令或新 L1SVC 操作升 MINOR，修复升 PATCH。</li></ul><h2 id="选择下一个版本" tabindex="-1">选择下一个版本 <a class="header-anchor" href="#选择下一个版本" aria-label="Permalink to &quot;选择下一个版本&quot;">​</a></h2><p>按上述 SemVer 规则；<code>build</code> = 发布日的提交计数 + 21——绝不手工 挑选。</p>',12)])])}const u=t(r,[["render",c]]);export{_ as __pageData,u as default};
